//! The compatibility layer: the OLD mod API's names, on the new one.
//!
//! The 137 machine modules were written against Horizon 9f42064's `Hooks`, `Host` and event structs
//! (`horizon_client::mod_api`). Migration step 1 keeps them as they are: a module's `use
//! horizon_client::mod_api::*` became `use crate::compat::*`, and this layer answers the rest.
//!
//! * `old_api.rs` (generated by tools/gen_compat.py): the old `Hooks`, its 75 events and the old `Host`.
//! * `types.rs`: old types the new API has no twin for, and the helper functions modules call.
//! * `adapter.rs`: `Host` for the new `ServerHost`/`ClientHost`; where the new API has no equivalent
//!   in a context, a method returns a neutral value and logs it once (`gap`).
//! * `events.rs`: the conversions from the new events to the old ones, used by the Parts.
//!
//! Everything the new API names the same way is re-exported rather than copied.

pub use mod_api::*;

mod old_api;
include!("old_names.rs");

mod types;
include!("types_names.rs");

pub mod adapter;
mod host_services;
pub use host_services::{register_containers, register_particles};
pub mod events;
pub use adapter::Adapter;

use std::collections::BTreeSet;
use std::sync::{Mutex, PoisonError};

/// Runs one module's hook so that a compatibility gap that panics (the old `Host` offered the server's services
/// everywhere; the adapter has none to give a client hook) costs that module's work, not the game.
///
/// A caught panic is not cheap: the game's panic hook runs first and captures a backtrace (seconds on Windows), so a
/// hook that panics every tick froze the client at 0.1 frames a second. The first panic of a (hook, module) pair is
/// logged and the pair is skipped from then on (`fallback` is what it answers); other modules keep their hook.
/// `module` is the module's index in `forward::Create::modules`.
pub fn guarded<R>(hook: &'static str, module: usize, fallback: R, call: impl FnOnce() -> R) -> R {
    use std::sync::atomic::{AtomicBool, Ordering};
    static ANY_BROKEN: AtomicBool = AtomicBool::new(false);
    static BROKEN: Mutex<BTreeSet<(&'static str, usize)>> = Mutex::new(BTreeSet::new());
    // Nothing has panicked yet: one atomic read per call.
    if ANY_BROKEN.load(Ordering::Relaxed) && BROKEN.lock().unwrap_or_else(PoisonError::into_inner).contains(&(hook, module)) {
        return fallback;
    }
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(call)) {
        Ok(answer) => answer,
        Err(payload) => {
            BROKEN.lock().unwrap_or_else(PoisonError::into_inner).insert((hook, module));
            ANY_BROKEN.store(true, Ordering::Relaxed);
            let message = payload
                .downcast_ref::<&str>()
                .map(|text| (*text).to_owned())
                .or_else(|| payload.downcast_ref::<String>().cloned())
                .unwrap_or_default();
            eprintln!("create: hook {hook} of module #{module} panicked and is skipped from now on: {message}");
            fallback
        }
    }
}

/// Records, once per name, that something asked the compatibility layer for what the new API has no match for.
/// The names it has seen are in `MIGRATION.md`'s gap list.
pub fn gap(name: &'static str) {
    static SEEN: Mutex<BTreeSet<&'static str>> = Mutex::new(BTreeSet::new());
    let mut seen = SEEN.lock().unwrap_or_else(PoisonError::into_inner);
    if seen.insert(name) {
        eprintln!("create: compat gap: Host::{name} has no match in the new API (neutral value returned)");
    }
}
